  const branch = req.body.branch;
  try{
    execSync(`cd &quot;${GIT_DIR}&quot; &amp;&amp; git pull &amp;&amp; git switch ${branch}`, {encoding:&#039;utf8&#039;});
    res.json({ok:true,msg:`✅ 已成功切换到分支：${branch}`});
  }catch(e){
    res.json({ok:false,error:`❌ 切换失败：${e.message}`});
  }
});

